import SwiftUI
struct DetailView: View {
    let item: ItemModel; @Environment(\.dismiss) private var dismiss; @State private var requested = false
    var body: some View {
        ZStack(alignment: .top) { VStack(spacing: 0) { BBVA.navy.frame(height: 420); BBVA.sand }.ignoresSafeArea(); ScrollView { VStack(spacing: -32) { hero; sheet } }.scrollIndicators(.hidden).ignoresSafeArea(edges: .top); HStack { Button { Haptics.tap(); dismiss() } label: { Image(systemName: "chevron.left").font(.system(size: 16, weight: .bold)).foregroundColor(.white).frame(width: 40, height: 40).background(Circle().fill(Color.white.opacity(0.14))) }.accessibilityLabel("Volver"); Spacer() }.padding(.horizontal, 20).padding(.top, 6) }
        .safeAreaInset(edge: .bottom) { Button("Solicitar ahora") { Haptics.success(); requested = true }.buttonStyle(PrimaryButtonStyle()).padding(.horizontal, 20).padding(.top, 12).padding(.bottom, 8).background(BBVA.sand.ignoresSafeArea(edges: .bottom)) }
        .navigationBarBackButtonHidden(true).toolbar(.hidden, for: .navigationBar)
        .alert("Solicitud enviada", isPresented: $requested) { Button("Aceptar", role: .cancel) {} } message: { Text("Un asesor BBVA se pondrá en contacto contigo.") }
    }
    private var hero: some View { VStack(spacing: 16) { ZStack { RoundedRectangle(cornerRadius: 36, style: .continuous).fill(Color.white.opacity(0.10)).frame(width: 112, height: 112).overlay(RoundedRectangle(cornerRadius: 36, style: .continuous).stroke(BBVA.aqua.opacity(0.6), lineWidth: 1)); Image(systemName: item.symbol).font(.system(size: 48, weight: .regular)).foregroundColor(.white) }; Text(item.category.rawValue.uppercased()).font(BBVAFont.body(11, .demi)).tracking(1.5).foregroundColor(BBVA.navy).padding(.horizontal, 12).padding(.vertical, 5).background(Capsule().fill(BBVA.aqua)); Text(item.name).font(BBVAFont.title(28)).multilineTextAlignment(.center).foregroundColor(.white); Text(item.subtitle).font(BBVAFont.body(16)).multilineTextAlignment(.center).foregroundColor(.white.opacity(0.75)) }.frame(maxWidth: .infinity).padding(.horizontal, 24).padding(.top, Inset.top + 56).padding(.bottom, 64).background(HeroBackground()) }
    private var sheet: some View { VStack(alignment: .leading, spacing: 24) { Text("Resumen").font(BBVAFont.title(20)).foregroundColor(BBVA.navy); LazyVGrid(columns: [GridItem(.flexible(), spacing: 12), GridItem(.flexible())], spacing: 12) { ForEach(item.attributes) { attr in StatTile(attribute: attr, tint: item.category.tint) } }; Text("Sobre este producto").font(BBVAFont.title(20)).foregroundColor(BBVA.navy); Text(item.summary).font(BBVAFont.body(16)).foregroundColor(BBVA.slate).lineSpacing(4); Text("Información referencial con fines académicos.").font(BBVAFont.body(11)).foregroundColor(BBVA.slate.opacity(0.8)) }.padding(.horizontal, 20).padding(.top, 28).padding(.bottom, 32).frame(maxWidth: .infinity, alignment: .leading).background(UnevenRoundedRectangle(topLeadingRadius: 32, topTrailingRadius: 32).fill(BBVA.sand)) }
}
struct StatTile: View { let attribute: ItemAttribute; let tint: Color; var body: some View { VStack(alignment: .leading, spacing: 10) { ZStack { Circle().fill(tint.opacity(0.12)); Image(systemName: attribute.symbol).font(.system(size: 15, weight: .semibold)).foregroundColor(tint) }.frame(width: 36, height: 36); Text(attribute.label).font(BBVAFont.body(12, .medium)).foregroundColor(BBVA.slate); Text(attribute.value).font(BBVAFont.body(15, .demi)).foregroundColor(BBVA.navy).fixedSize(horizontal: false, vertical: true) }.padding(14).frame(maxWidth: .infinity, minHeight: 140, alignment: .topLeading).background(RoundedRectangle(cornerRadius: 20, style: .continuous).fill(Color.white).shadow(color: BBVA.navy.opacity(0.06), radius: 10, y: 3)) } }
